-- ============================================================================
-- B5 FOLLOW-ON W1 (grade integrity): rodpump.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 4 and
-- the annotations in docs/graded-field-audit/annot/rodpump.json. Owner
-- approved D1 to D7 as recommended, 2026-09-21.
--
-- BEGINNER
--   string_natural_freq_spm is the product of two numbers the prompt printed
--   (the 40.15458511 spm uniform fundamental and the 1.15865923 taper factor),
--   so 40.15458511 x 1.15865923 = 46.52548066 passed without any work (B5
--   finding 4). The two figures are dropped from the trap and the free check,
--   keeping the qualitative check that the tapered note exceeds the uniform one.
--   The tapered note is a transfer matrix scan with no hand route, so the string
--   explorer (pd-string-explorer) gains a typed string view ('The note of a
--   string you type'): the learner enters the three sections the prompt states
--   and reads the engine scan fundamental at 12 decimals. The view opens on the
--   ODUMA-4 teaching string, so its default state lands on no graded answer
--   (panelCapstoneGuard sweeps it). Key, expected and tolerance are unchanged;
--   prompt only.
--   PROMPT was: A stepped bar has a fundamental of its own, 40.15458511 spm
--   here, and a taper raises it by a taper factor of 1.15865923; report the
--   TAPERED string's note, not the uniform one.
--   PROMPT now: A uniform bar of the same length has a fundamental of its own,
--   and a taper raises it by a taper factor; report the TAPERED string's note,
--   which the string explorer's typed string view reads from the three sections
--   stated above.
--   PROMPT was: Field 3 must EXCEED the 40.15458511 spm uniform fundamental, by
--   exactly the taper factor, because stiffening the top of a bar can only raise
--   its note.
--   PROMPT now: Field 3 must EXCEED the fundamental of a uniform bar of the same
--   length, by exactly the taper factor, because stiffening the top of a bar can
--   only raise its note.
--
-- WHAT DOES NOT MOVE. Every other field (key, label, unit, expected, tol and
-- position), the title, dataset, status and the row itself.
--
-- ATTEMPTS. This file moves no graded key or tolerance (prompt copy only), so
-- no attempt can be graded differently and there is no attempts guard.
--
-- GUARDS. Each row must hold EITHER its published prompt (by md5) and fields
-- (exact jsonb) as the post-20261023 scratch replay has them (it is
-- rewritten), OR its W1 form (left alone). Anything else raises and the whole
-- file rolls back. A file that will write first checks the round-off
-- post-state (20261023*) and refuses without it. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN: a second run
-- writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
begin
  -- rodpump / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'rodpump' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 rodpump refused: rodpump/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '27fc6852586864af77f23cdbbf2deacc' and fields = '[{"key": "string_kr_lb_per_in", "tol": 0.000048, "unit": "lb/in", "label": "Rod string spring rate", "expected": 237.9571451078754}, {"key": "string_buoyed_weight_lb", "tol": 0.0024, "unit": "lbf", "label": "Buoyed string weight", "expected": 11903.896611464968}, {"key": "string_natural_freq_spm", "tol": 0.0000094, "unit": "spm", "label": "Natural frequency", "expected": 46.52548077425118}, {"key": "unit_stroke_in", "tol": 0.000025, "unit": "in", "label": "Surface stroke", "expected": 121.38337590532858}, {"key": "pump_fluid_load_lb", "tol": 0.00088, "unit": "lbf", "label": "Fluid load", "expected": 4364.850293081319}, {"key": "pump_rated_displacement_bpd", "tol": 0.000073, "unit": "bbl/d", "label": "Rated displacement", "expected": 362.9423814326748}]'::jsonb then 'old'
              when md5(prompt) = 'f09343bae3c9691c79eb2815b5258024' and fields = '[{"key": "string_kr_lb_per_in", "tol": 0.000048, "unit": "lb/in", "label": "Rod string spring rate", "expected": 237.9571451078754}, {"key": "string_buoyed_weight_lb", "tol": 0.0024, "unit": "lbf", "label": "Buoyed string weight", "expected": 11903.896611464968}, {"key": "string_natural_freq_spm", "tol": 0.0000094, "unit": "spm", "label": "Natural frequency", "expected": 46.52548077425118}, {"key": "unit_stroke_in", "tol": 0.000025, "unit": "in", "label": "Surface stroke", "expected": 121.38337590532858}, {"key": "pump_fluid_load_lb", "tol": 0.00088, "unit": "lbf", "label": "Fluid load", "expected": 4364.850293081319}, {"key": "pump_rated_displacement_bpd", "tol": 0.000073, "unit": "bbl/d", "label": "Rated displacement", "expected": 362.9423814326748}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'rodpump' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 rodpump refused: rodpump/beginner matches neither its published form (prompt md5 27fc6852586864af77f23cdbbf2deacc) nor its W1 form (prompt md5 f09343bae3c9691c79eb2815b5258024), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' then
    raise notice 'w1 rodpump: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 rodpump refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Six values for OBAGI-27 that are settled BEFORE a single time step is taken, and there is deliberately no card in this question. THE STRING is a three-way taper hanging 6085 ft: 1825 ft of 1 in rod at the top, then 2140 ft of 7/8 in, then 2120 ft of 3/4 in at the bottom, all API GRADE D, hanging in a fluid of SPECIFIC GRAVITY 0.94. THE UNIT is conventional, and these are its own drawing dimensions: a walking beam with a 118.4 in FRONT arm from the saddle bearing to the polished rod and a 71.6 in REAR arm from the saddle bearing to the equalizer, a 92.5 in pitman, a crank pivot 104.3 in behind and 66.9 in below the saddle bearing, and a 33.7 in crank radius. Close the linkage at 720 CRANK ANGLES. THE PUMP has a 1.5 IN PLUNGER, an intake pressure of 210 PSIA and a discharge pressure of 2680 PSIA, and the unit runs at 11.4 SPM. What the barrel actually fills, how efficient the pump is and how heavily the string is damped are the Professional tier''s to work out and are not needed here. Report: (1) the SPRING RATE of the string; (2) its BUOYED WEIGHT; (3) its NATURAL FREQUENCY; (4) the SURFACE STROKE the linkage gives; (5) the FLUID LOAD on the plunger; and (6) the RATED DISPLACEMENT. Traps. Field 2 is not the weight in air. The string weighs 13,523.24 lb dry, and the buoyancy factor comes from the 0.94 fluid rather than from water, so a design worked in water is wrong in the third figure and wrong in the same direction on every load that follows it. Field 3 has TWO candidate answers and only one is asked for. A uniform bar of the same length has a fundamental of its own, and a taper raises it by a taper factor; report the TAPERED string''s note, which the string explorer''s typed string view reads from the three sections stated above. Field 4 has the same shape of trap from the other direction: the textbook shorthand of twice the crank radius times the front arm over the rear arm gives 111.45474860 in on this unit, and the four-bar closed properly gives something 9.93 in longer, because a pitman of finite length is not a rigid link of zero mass and the shorthand is a small-angle approximation nobody states. Field 5 is a DIFFERENTIAL times an AREA and nothing else: no depth, no specific gravity, no fillage. Field 6 is a RATING and not a production forecast: it is the pump constant times the plunger diameter SQUARED times the SURFACE stroke times the speed, with no barrel fillage and no pump efficiency in it, so it is the largest number this well can be made to produce and not a number it will. Free checks: field 2 divided by the 13,523.24 lb weight in air must equal one less the fluid''s own weight over steel''s, and must therefore be the SAME buoyancy factor for every taper hung in this fluid. Field 3 must EXCEED the fundamental of a uniform bar of the same length, by exactly the taper factor, because stiffening the top of a bar can only raise its note. Field 4 must EXCEED 111.45474860 in, and if your linkage returns something below it you have closed the four-bar on the wrong branch. Field 5 divided by the plunger area must return 2470 psi exactly, the differential and nothing else. Field 6 divided by field 4, then by 11.4, then by 1.5 squared, must return the package''s own pump constant of 0.11657115597735782 bbl per day per in2 per in per spm, which is built from 42 gallons of 231 in3 rather than stored, so the same division done against a stored constant off a chart will miss in the sixth figure. And the 11.4 spm the unit runs at must sit WELL BELOW field 3, since a beam pump run near the string''s own note is a different design problem from this one.',
           fields = '[{"key": "string_kr_lb_per_in", "tol": 0.000048, "unit": "lb/in", "label": "Rod string spring rate", "expected": 237.9571451078754}, {"key": "string_buoyed_weight_lb", "tol": 0.0024, "unit": "lbf", "label": "Buoyed string weight", "expected": 11903.896611464968}, {"key": "string_natural_freq_spm", "tol": 0.0000094, "unit": "spm", "label": "Natural frequency", "expected": 46.52548077425118}, {"key": "unit_stroke_in", "tol": 0.000025, "unit": "in", "label": "Surface stroke", "expected": 121.38337590532858}, {"key": "pump_fluid_load_lb", "tol": 0.00088, "unit": "lbf", "label": "Fluid load", "expected": 4364.850293081319}, {"key": "pump_rated_displacement_bpd", "tol": 0.000073, "unit": "bbl/d", "label": "Rated displacement", "expected": 362.9423814326748}]'::jsonb
     where app_slug = 'rodpump' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 rodpump refused: rodpump/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'f09343bae3c9691c79eb2815b5258024' and fields = '[{"key": "string_kr_lb_per_in", "tol": 0.000048, "unit": "lb/in", "label": "Rod string spring rate", "expected": 237.9571451078754}, {"key": "string_buoyed_weight_lb", "tol": 0.0024, "unit": "lbf", "label": "Buoyed string weight", "expected": 11903.896611464968}, {"key": "string_natural_freq_spm", "tol": 0.0000094, "unit": "spm", "label": "Natural frequency", "expected": 46.52548077425118}, {"key": "unit_stroke_in", "tol": 0.000025, "unit": "in", "label": "Surface stroke", "expected": 121.38337590532858}, {"key": "pump_fluid_load_lb", "tol": 0.00088, "unit": "lbf", "label": "Fluid load", "expected": 4364.850293081319}, {"key": "pump_rated_displacement_bpd", "tol": 0.000073, "unit": "bbl/d", "label": "Rated displacement", "expected": 362.9423814326748}]'::jsonb) from public.academy_capstones where app_slug = 'rodpump' and tier = 'beginner' and active) is not true then
    raise exception 'w1 rodpump refused: rodpump/beginner does not read back as its W1 form';
  end if;

  raise notice 'w1 rodpump: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
